package com.pickleball.booking.coach.infrastructure;
import java.util.*; import org.springframework.data.jpa.repository.*; import jakarta.persistence.LockModeType;
public interface AvailabilityProposalRepository extends JpaRepository<AvailabilityProposalEntity, UUID> { List<AvailabilityProposalEntity> findByOrganizationIdOrderByStartAtDesc(UUID org); List<AvailabilityProposalEntity> findByOrganizationIdAndStatusAndStartAtAfterOrderByStartAtAsc(UUID org, com.pickleball.booking.coach.domain.AvailabilityProposalStatus status, java.time.Instant after); List<AvailabilityProposalEntity> findByCoachProfileIdOrderByStartAtDesc(UUID profile); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select a from AvailabilityProposalEntity a where a.id=:id") Optional<AvailabilityProposalEntity> findLockedById(UUID id); }
